import assert from 'node:assert/strict';import{readFileSync}from'node:fs';import{execFileSync}from'node:child_process';import{createHash}from'node:crypto';
import {verifyInstructionCandidate,readBeforeInstructionCandidate} from './check-instruction-candidate.mjs';
const localCandidates=new WeakMap();
const base='995ae4407c6b9c0765cf63f801009846ca30ed11',folder='docs/goal-audit-20261101/',floor='docs/appearance-floor-20261031/floor.json';
const git=(...a)=>execFileSync('git',a,{maxBuffer:128e6}),sha=b=>createHash('sha256').update(b).digest('hex'),lines=b=>b.toString().trim().split('\n').filter(Boolean),sort=a=>a.sort((a,b)=>a.localeCompare(b));
const roots=['app','components','hooks','data','lib','public','scripts','db','drizzle','.github','AGENTS.md','PUBLICATIE.md','VORMGEVING-VASTGEZET.md','docs/appearance-floor-20261031','docs/KLINK-DOCENTHANDLEIDING.md','vite.config.ts','next.config.ts','package.json','package-lock.json','wrangler.jsonc'];
export function verifyGoalAuditRelease(read=readFileSync){
 const candidate=verifyInstructionCandidate(read),currentRead=read;read=file=>readBeforeInstructionCandidate(file,candidate,currentRead);
 const json=f=>JSON.parse(read(f)),r=json('docs/klink-owner-release-goal-audit-20261101.json');assert.equal(r.approvedBy,'Nico');assert(r.publicationApproved&&r.appearanceChangeApproved);assert.equal(r.baselineSourceCommit,base);assert.equal(r.liveSourceCommit,base);assert(r.userRequest.includes('Controleer nu bij alle oefenvormen'));git('merge-base','--is-ancestor',base,'HEAD');
 const changed=sort(candidate?lines(git('diff','--name-only',base,candidate.baselineSourceCommit,'--',...roots)):[...new Set([...lines(git('diff','--name-only',base,'--',...roots)),...lines(git('ls-files','--others','--exclude-standard','--',...roots))])]);assert.deepEqual(changed,sort([...r.changedFiles,floor,r.approval]));assert.deepEqual(sort(Object.keys(r.files)),r.changedFiles);for(const[f,h]of Object.entries(r.files))assert.equal(sha(read(f)),h,f);for(const[f,h]of Object.entries(r.evidenceFiles))assert.equal(sha(read(f)),h,f);
 assert.equal(git('diff','--name-only',base,...(candidate?[candidate.baselineSourceCommit]:[]),'--','hooks','lib','public','db','drizzle','.github','AGENTS.md','package.json','package-lock.json','vite.config.ts').length,0,'Keep all exercises, media, audio, scoring, storage, routes and dependencies');
 const runtime=changed.filter(f=>/^(app|components|data)\//.test(f));assert.deepEqual(runtime,sort(['app/learner-layout.css','app/learner-ui.css','components/product/exercise-listen.tsx','components/product/package-group-practice.tsx','data/klink-learning-goals.json']));assert(read('app/learner-layout.css').toString().startsWith(git('show',base+':app/learner-layout.css').toString()));
 const oldFloor=JSON.parse(git('show',base+':'+floor));assert.deepEqual(json(floor),{...oldFloor,approvedUpdates:[...oldFloor.approvedUpdates,r.approval]});const a=json(r.approval);assert.equal(a.userRequest,r.userRequest);assert.deepEqual(a.files,Object.fromEntries(runtime.map(f=>[f,r.files[f]])));
 const review=json(folder+'review.json');assert.equal(review.activities,59);assert.equal(review.modes,50);assert.equal(review.instances,99732);assert.equal(review.uniqueIds,68035);assert.equal(review.goals,108);assert.equal(review.sourceObjectives,279);const edits=json(folder+'goal-corrections.json');assert.equal(edits.changes.length,20);assert.equal(Object.keys(edits.newGoals).length,11);assert.equal(Object.keys(edits.updates).length,3);
 const browser=json(folder+'local/goals.json');assert.equal(browser.checks.length,202);assert.deepEqual(browser.errors,[]);assert(browser.checks.every(c=>c.infoInHeader&&c.infoCount===1&&c.actualGoal===c.goal&&c.goalFits&&c.keyboardContained&&c.storagePreserved));
 const interactions=json(folder+'local/interactions.json');assert.equal(interactions.checks.length,100);assert.equal(new Set(interactions.checks.map(c=>c.engine+':'+c.mode)).size,100);assert.deepEqual(interactions.errors,[]);assert(interactions.checks.every(c=>(c.next||c.nextWithinWorkflow)&&c.storagePreserved));
 const sheets=json(folder+'local/sheets.json');assert.equal(sheets.checks.length,96);assert.deepEqual(sheets.errors,[]);const writing=json(folder+'local/writing.json');assert.equal(writing.checks.length,16);assert.equal(writing.audioNext.length,12);assert.equal(writing.native.length,2);assert.deepEqual(writing.errors,[]);
 const p=json(folder+'verification.json');for(const k of['types','lint','unit','allMappings','sourceBoundReview','mobileAnswersAndNext','headerConsistency','keyboard','privacyPreserved','contentAudioAndProgressPreserved','reactReview','localOnly'])assert.equal(p[k],true,k);
 const backup=json(folder+'backup.json');assert(backup.verified&&backup.fullReadback&&backup.zipIntegrity&&backup.driveId);assert.deepEqual(backup.files,r.files);assert.deepEqual(backup.evidenceFiles,r.evidenceFiles);if(candidate)localCandidates.set(r,candidate);return r;
}
export function readBeforeGoalAudit(file,r,read=readFileSync){return r.changedFiles.includes(file)||file===floor?git('show',base+':'+file):readBeforeInstructionCandidate(file,localCandidates.get(r),read);}
